SELECT YEAR(customers.signup_date) AS signup_year, CASE WHEN customers.country IN ('JP', 'DE') THEN 'core' ELSE 'other' END AS country_group, COUNT(CASE WHEN sessions.device = 'mobile' THEN 1 END) AS mobile_count, MAX(sessions.started_at) AS latest_started_at FROM sessions INNER JOIN customers ON sessions.customer_id = customers.id GROUP BY YEAR(customers.signup_date), CASE WHEN customers.country IN ('JP', 'DE') THEN 'core' ELSE 'other' END HAVING COUNT(CASE WHEN sessions.device = 'mobile' THEN 1 END) > 3;
